SELECT * FROM settlement_bank_interface_config


        AND bank_code = #{bankCode}


        AND interface_type = #{interfaceType}


        AND is_enabled = #{isEnabled}


        AND org_id = #{orgId}


ORDER BY priority DESC, create_time DESC

SELECT * FROM settlement_bank_interface_config
WHERE bank_code = #{bankCode} AND org_id = #{orgId}
ORDER BY priority DESC

SELECT * FROM settlement_bank_interface_config
WHERE interface_type = #{interfaceType} AND org_id = #{orgId}
ORDER BY priority DESC

SELECT * FROM settlement_bank_interface_config
WHERE is_enabled = 1 AND org_id = #{orgId}
ORDER BY priority DESC, create_time DESC

SELECT * FROM settlement_bank_interface_config
WHERE is_enabled = 1 
AND interface_type = #{interfaceType}
AND (health_status IS NULL OR health_status = 'HEALTHY')
AND org_id = #{orgId}
ORDER BY priority DESC, load_balance_weight DESC
